{
  "name": "opencode-daily",
  "version": "0.1.0",
  "description": "OpenCode plugin: injects a fresh local date/time into every user message and adds a Scrum daily log (/standup + daily_log tool).",
  "type": "module",
  "license": "MIT",
  "author": "Julianste15",
  "homepage": "https://github.com/Julianste15/opencode-daily#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Julianste15/opencode-daily.git"
  },
  "bugs": {
    "url": "https://github.com/Julianste15/opencode-daily/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "date",
    "time",
    "timezone",
    "scrum",
    "daily",
    "standup",
    "standup-log"
  ],
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./utils": {
      "types": "./dist/utils.d.ts",
      "import": "./dist/utils.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:watch": "vitest",
    "prepublishOnly": "npm run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.19.1",
    "@types/node": "^22.0.0",
    "tsup": "^8.3.5",
    "typescript": "^5.7.2",
    "vitest": "^2.1.8"
  }
}
